mapper.update:
UPDATE itinerary_command
SET result_itinerary_id = #{itineraryId}, result_item_id = #{itemId}, result_version = #{version}
WHERE command_id = #{commandId} AND result_itinerary_id IS NULL AND result_version IS NULL

UPDATE itinerary_item
SET deleted_at = #{now}, updated_at = #{now}
WHERE id = #{itemId} AND itinerary_id = #{itineraryId} AND deleted_at IS NULL

UPDATE itinerary_item
SET position = #{position}, updated_at = #{now}
WHERE id = #{itemId} AND itinerary_id = #{itineraryId}
  AND itinerary_day_id = #{dayId} AND deleted_at IS NULL

UPDATE itinerary
SET title = #{title}, start_date = #{startDate}, end_date = #{endDate},
    time_zone = #{timeZone}, base_currency = #{baseCurrency},
    version = #{nextVersion}, updated_at = #{now}
WHERE id = #{itineraryId} AND version = #{expectedVersion}

UPDATE itinerary
SET version = #{nextVersion}, updated_at = #{now}
WHERE id = #{itineraryId} AND version = #{expectedVersion}

mapper.select:
SELECT i.id, i.title, i.start_date, i.end_date,
       (SELECT d.name FROM itinerary_destination d
        WHERE d.itinerary_id = i.id ORDER BY d.position, d.id LIMIT 1) AS primary_destination,
       i.status, i.version, i.updated_at
FROM itinerary i
WHERE i.owner_member_id = #{ownerMemberId}
  AND i.status IN

    #{status}


    AND (i.updated_at < #{cursorUpdatedAt}
         OR (i.updated_at = #{cursorUpdatedAt} AND i.id < #{cursorId}))

ORDER BY i.updated_at DESC, i.id DESC
LIMIT #{limit}
